<?php
namespace App\Http\Controllers\Api;use App\Http\Controllers\Controller;use App\Services\AuditService;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;
class DocumentController extends Controller{public function templates(Request $r):JsonResponse{return $this->success(['items'=>DB::table('document_templates')->where('organization_id',$r->attributes->get('organization_id'))->orderBy('name')->get()->map(fn($t)=>['id'=>$t->id,'templateKey'=>$t->template_key,'name'=>$t->name,'category'=>$t->category,'locale'=>$t->locale,'active'=>(bool)$t->active])]);}public function documents(Request $r):JsonResponse{return $this->success(['items'=>DB::table('generated_documents')->where('organization_id',$r->attributes->get('organization_id'))->latest('generated_at')->get()->map(fn($d)=>$this->documentData($d))]);}public function context(Request $r,string $id):JsonResponse{$x=$this->receivable($r,$id);return $this->success(['receivableId'=>$x->id,'tenantId'=>$x->tenant_id,'tenantName'=>$x->tenant_name,'dueDate'=>$x->due_date,'originalAmount'=>(float)$x->original_amount,'balance'=>$this->balance($x->id,(float)$x->original_amount),'allowedTemplateKeys'=>['payment_demand']]);}public function draft(Request $r,string $id):JsonResponse{$d=$r->validate(['templateKey'=>['required','string','max:100'],'locale'=>['required','string','max:10'],'renderedBody'=>['nullable','string','max:30000']]);$org=$r->attributes->get('organization_id');$x=$this->receivable($r,$id);$balance=$this->balance($x->id,(float)$x->original_amount);if($balance<=0)abort(409,'لا يمكن إصدار خطاب لاستحقاق مسدد أو ملغى.');$template=DB::table('document_templates')->where('organization_id',$org)->where('template_key',$d['templateKey'])->where('locale',$d['locale'])->where('active',true)->first();$version=$template?DB::table('document_template_versions')->where('template_id',$template->id)->whereNotNull('published_at')->latest('version_no')->first():null;$body=$d['renderedBody']??($version?str_replace(['{{tenantName}}','{{balance}}','{{dueDate}}'],[$x->tenant_name,number_format($balance,2),$x->due_date],$version->body):"السادة/ {$x->tenant_name}\n\nنرجو سداد مبلغ ".number_format($balance,2)." المستحق بتاريخ {$x->due_date}.");$result=DB::transaction(function()use($org,$r,$x,$template,$version,$body,$d){$docId=(string)Str::uuid();DB::table('generated_documents')->insert(['id'=>$docId,'organization_id'=>$org,'template_version_id'=>$version?->id,'entity_type'=>'receivable','entity_id'=>$x->id,'rendered_body'=>$body,'status'=>'generated','generated_by'=>$r->user()->id,'generated_at'=>now()]);$followId=(string)Str::uuid();DB::table('collection_follow_ups')->insert(['id'=>$followId,'organization_id'=>$org,'receivable_id'=>$x->id,'generated_document_id'=>$docId,'template_key'=>$d['templateKey'],'channel'=>'manual','status'=>'draft','created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);AuditService::record($org,$r->user()->id,'demand_letter.drafted','generated_document',$docId,null,['receivableId'=>$x->id]);return ['generatedDocument'=>DB::table('generated_documents')->find($docId),'collectionFollowUp'=>DB::table('collection_follow_ups')->find($followId)];});return $this->success(['generatedDocument'=>$this->documentData($result['generatedDocument']),'collectionFollowUp'=>['id'=>$result['collectionFollowUp']->id,'status'=>$result['collectionFollowUp']->status,'channel'=>$result['collectionFollowUp']->channel]] ,[],201);}public function export(Request $r,string $id):JsonResponse{$d=DB::table('generated_documents')->where('organization_id',$r->attributes->get('organization_id'))->find($id);if(!$d)abort(404);return $this->success(['id'=>$d->id,'filename'=>'document-'.$d->id.'.html','contentType'=>'text/html','content'=>"<html dir=\"rtl\"><meta charset=\"utf-8\"><body style=\"font-family:Tahoma;white-space:pre-wrap\">".e($d->rendered_body).'</body></html>']);}public function send(Request $r,string $id):JsonResponse{$d=$r->validate(['channel'=>['required','in:email,sms,whatsapp,manual'],'recipient'=>['required','string','max:255']]);$org=$r->attributes->get('organization_id');$f=DB::transaction(function()use($r,$id,$d,$org){$f=DB::table('collection_follow_ups')->where('organization_id',$org)->where('id',$id)->lockForUpdate()->first();if(!$f)abort(404);$x=$this->receivable($r,$f->receivable_id);if($this->balance($x->id,(float)$x->original_amount)<=0)abort(409,'لا يمكن إرسال خطاب لاستحقاق مسدد.');DB::table('collection_follow_ups')->where('id',$id)->update(['channel'=>$d['channel'],'recipient'=>$d['recipient'],'status'=>'sent','updated_at'=>now()]);DB::table('communication_logs')->insert(['id'=>(string)Str::uuid(),'organization_id'=>$org,'follow_up_id'=>$id,'channel'=>$d['channel'],'recipient'=>$d['recipient'],'status'=>'sent','created_at'=>now()]);if($f->generated_document_id)DB::table('generated_documents')->where('id',$f->generated_document_id)->update(['status'=>'sent']);AuditService::record($org,$r->user()->id,'collection_follow_up.sent','collection_follow_up',$id,null,['channel'=>$d['channel'],'recipient'=>$d['recipient']]);return DB::table('collection_follow_ups')->find($id);});return $this->success(['id'=>$f->id,'status'=>$f->status,'channel'=>$f->channel,'recipient'=>$f->recipient]);}private function receivable(Request $r,string $id):object{$org=$r->attributes->get('organization_id');$x=DB::table('receivables')->join('tenants','tenants.id','=','receivables.tenant_id')->where('receivables.organization_id',$org)->where('receivables.id',$id)->whereNull('receivables.cancelled_at')->select('receivables.*','tenants.full_name as tenant_name')->first();if(!$x)abort(404);return $x;}private function balance(string $id,float $original):float{$paid=(float)DB::table('payment_allocations as pa')->join('payments as p','p.id','=','pa.payment_id')->where('pa.receivable_id',$id)->where('p.status','confirmed')->sum('pa.amount');return max(0,$original-$paid);}private function documentData(object $d):array{return ['id'=>$d->id,'entityType'=>$d->entity_type,'entityId'=>$d->entity_id,'status'=>$d->status,'renderedBody'=>$d->rendered_body,'generatedAt'=>$d->generated_at];}}
